begin;
create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select plan(18);
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data)values('19000000-0000-4000-8000-000000000001','recurring-owner@example.test','{}','{}'),('19000000-0000-4000-8000-000000000002','recurring-outsider@example.test','{}','{}');
insert into public.workspaces(id,name,owner_id)values('29000000-0000-4000-8000-000000000001','Recurring Workspace','19000000-0000-4000-8000-000000000001'),('29000000-0000-4000-8000-000000000002','Other Workspace','19000000-0000-4000-8000-000000000002');
insert into public.categories(id,workspace_id,name,kind,created_by)values('39000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000001','Software','expense','19000000-0000-4000-8000-000000000001'),('39000000-0000-4000-8000-000000000002','29000000-0000-4000-8000-000000000002','Other software','expense','19000000-0000-4000-8000-000000000002');
set local role authenticated;select throws_ok($$select public.mutate_recurring_expense('29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001','recurring-denied','create',null,null,'x','{}')$$,'42501',null,'authenticated clients cannot call the service-role function');reset role;
create temporary table recurring_create as select public.mutate_recurring_expense('29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001','recurring-create-key','create',null,null,'create-hash','{"categoryId":"39000000-0000-4000-8000-000000000001","vendorName":"Canva","productName":"Canva Pro","purpose":"Listing marketing","recurringType":"subscription","amount":"14.99","cadence":"monthly","annualizedAmount":"179.88","nextDueDate":"2026-09-15","autoPay":true,"reminderDays":7,"isActive":true,"deviceId":"database-test"}')result;
select is((select result->>'version'from recurring_create),'1','obligation starts at version one');select is((select annualized_amount::text from public.recurring_expenses where id=(select(result->>'id')::uuid from recurring_create)),'179.88','annualized cost is calculated exactly');select is((select recurring_type from public.recurring_expenses where id=(select(result->>'id')::uuid from recurring_create)),'subscription','subscription type is retained');select is((select count(*)::integer from public.sync_operations where client_mutation_id='recurring-create-key'),1,'create writes one sync receipt');select is((select count(*)::integer from public.audit_events where request_id='recurring-create-key'),1,'create writes one audit event');
select is(public.mutate_recurring_expense('29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001','recurring-create-key','create',null,null,'create-hash','{}')->>'id',(select result->>'id'from recurring_create),'identical retry returns the original obligation');
select throws_ok($$select public.mutate_recurring_expense('29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001','recurring-cross-category','create',null,null,'cross-hash','{"categoryId":"39000000-0000-4000-8000-000000000002","vendorName":"Bad","recurringType":"subscription","amount":"10","cadence":"monthly","nextDueDate":"2026-09-15","reminderDays":7}')$$,'P0001','Expense category is not available in this workspace','cross-workspace categories are rejected');
create temporary table recurring_update as select public.mutate_recurring_expense('29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001','recurring-update-key','update',(select(result->>'id')::uuid from recurring_create),1,'update-hash','{"categoryId":"39000000-0000-4000-8000-000000000001","vendorName":"Canva","productName":"Canva Teams","purpose":"Marketing design","recurringType":"subscription","amount":"20.00","cadence":"monthly","nextDueDate":"2026-09-15","autoPay":true,"reminderDays":10,"isActive":true,"deviceId":"database-test"}')result;
select is((select result->>'version'from recurring_update),'2','update increments the obligation version');
select throws_ok(format($$select public.mutate_recurring_expense('29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001','recurring-stale-key','update',%L,1,'stale','{"vendorName":"Stale","recurringType":"subscription","amount":"10","cadence":"monthly","nextDueDate":"2026-09-15","reminderDays":7}')$$,(select result->>'id'from recurring_create)),'40001','Record version conflict','stale updates are rejected');
create temporary table recurring_advance as select public.mutate_recurring_expense('29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001','recurring-renew-key','advance',(select(result->>'id')::uuid from recurring_create),2,'renew-hash','{"paidDate":"2026-09-15","deviceId":"database-test"}')result;
select is((select result->>'version'from recurring_advance),'3','renewal confirmation increments the version');select is((select count(*)::integer from public.recurring_expense_renewals where recurring_expense_id=(select(result->>'id')::uuid from recurring_create)),1,'renewal history is retained');select is((select next_due_date::text from public.recurring_expenses where id=(select(result->>'id')::uuid from recurring_create)),'2026-10-15','renewal advances from the scheduled due date');select is((select count(*)::integer from public.transactions where workspace_id='29000000-0000-4000-8000-000000000001'),0,'renewal confirmation does not duplicate the bank-first ledger');select is((select action from public.audit_events where request_id='recurring-renew-key'),'advance','renewal action is explicit in the audit trail');select is(public.mutate_recurring_expense('29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001','recurring-renew-key','advance',null,null,'renew-hash','{}')->>'version','3','renewal retry is idempotent');
select public.mutate_recurring_expense('29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001','recurring-void-key','void',(select(result->>'id')::uuid from recurring_create),3,'void-hash','{"reason":"Subscription canceled","deviceId":"database-test"}');select ok((select deleted_at is not null and not is_active and void_reason='Subscription canceled'from public.recurring_expenses where id=(select(result->>'id')::uuid from recurring_create)),'voiding is non-destructive and retains the reason');
select throws_ok($$select public.mutate_recurring_expense('29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000002','recurring-unauthorized','create',null,null,'x','{"vendorName":"No access","recurringType":"subscription","amount":"10","cadence":"monthly","nextDueDate":"2026-09-15","reminderDays":7}')$$,'P0001','Not authorized to change recurring expenses','service function rechecks actor membership');
select * from finish();rollback;
